}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    // Helper lambda for bounds checking
    java.util.function.BiPredicate<Integer, Integer> inBounds = (x, y) -> x >= 0 && x < n && y >= 0 && y < n;
    // Helper lambda for key generation
    java.util.function.BiFunction<Integer, Integer, String> toKey = (x, y) -> x + "," + y;

    String startKey = toKey.apply(start[0], start[1]);
    String endKey   = toKey.apply(end[0],   end[1]);

    // Quick check for same start and end
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }

    // Build graph adjacency representation
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    graph.put(startKey, new java.util.ArrayList<>());
    graph.put(endKey,   new java.util.ArrayList<>());

    if (paths != null) {
        for (int[] p : paths) {
            if (p == null || p.length != 4) continue;
            int x1 = p[0], y1 = p[1], x2 = p[2], y2 = p[3];
            if (!inBounds.test(x1, y1) || !inBounds.test(x2, y2)) continue;
            String a = toKey.apply(x1, y1);
            String b = toKey.apply(x2, y2);
            graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
            graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
        }
    }

    // Breadth-first search for connectivity
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        java.util.List<String> neighbors = graph.getOrDefault(cur, java.util.Collections.emptyList());
        for (String nb : neighbors) {
            if (visited.add(nb)) {
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

