        }
        uniqueSet.add(sb.toString());
    }
    return uniqueSet.size();
}

public boolean hasAllCodes(String s, int k) {
    if (s == null) {
        return false;
    }

    int n = s.length();

    if (k <= 0) {
        // Empty binary string always present
        return true;
    }

    if (n < k) {
        return false;
    }

    // Guard against overflow for large k
    if (k > 20) { // 2^21 is already > 2 million, beyond reasonable array size
        return false;
    }

    int total = 1 << k;                 // Total possible binary strings of length k
    boolean[] seen = new boolean[total];
    int mask = total - 1;                // To keep only the last k bits
    int code = 0;

    // Build the first code of length k
    for (int i = 0; i < k; i++) {
        code = (code << 1) | (s.charAt(i) - '0');
    }
    seen[code] = true;
    int count = 1;

    // Slide over the string, updating code efficiently
    for (int i = k; i < n; i++) {
        code = ((code << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[code]) {
            seen[code] = true;
            count++;
            if (count == total) {
                return true; // All codes seen
            }
        }
    }

    return count == total;
}

