public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }

    int currentMax = 0;
    int maxSum = Integer.MIN_VALUE;

    int currentMin = 0;
    int minSum = Integer.MAX_VALUE;

    for (int n : nums) {
        // Max subarray sum (Kadane's algorithm)
        currentMax = Math.max(n, currentMax + n);
        if (currentMax > maxSum) {
            maxSum = currentMax;
        }

        // Min subarray sum
        currentMin = Math.min(n, currentMin + n);
        if (currentMin < minSum) {
            minSum = currentMin;
        }
    }

    return Math.max(maxSum, Math.abs(minSum));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
    fibs.add(1);
    while (true) {
        int sz = fibs.size();
        int next = fibs.get(sz - 1) + fibs.get(sz - 2);
        if (next > k) break;
        fibs.add(next);
    }

    // greedy subtraction from the largest Fibonacci number
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int fib = fibs.get(i);
        while (remaining >= fib) {
            remaining -= fib;
            count++;
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    if (n <= 0 || k <= 0) return -1; // Defensive check for positive inputs
    java.util.List<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) factors.add(other);
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) return -1;
    return factors.get(k - 1);
}

public String makeGood(String s) {
    if (s == null) {
        return "";
    }
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char curr = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char top = stack.charAt(len - 1);
            if (Character.toLowerCase(top) == Character.toLowerCase(curr) &&
                Character.isUpperCase(top) != Character.isUpperCase(curr)) {
                stack.deleteCharAt(len - 1); // remove the matched pair
                continue;
            }
        }
        stack.append(curr);
    }
    return stack.toString();
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) {
        return 0;
    }
    int n = s.length();
    int best = 0;
    java.util.ArrayDeque<Integer> idxStack = new java.util.ArrayDeque<>();
    java.util.ArrayDeque<java.util.Set<String>> setStack = new java.util.ArrayDeque<>();
    idxStack.push(0);
    setStack.push(new java.util.HashSet<String>());
    while (!idxStack.isEmpty()) {
        int idx = idxStack.pop();
        java.util.Set<String> used = setStack.pop();
        if (idx == n) {
            if (used.size() > best) {
                best = used.size();
            }
            continue;
        }
        for (int end = idx + 1; end <= n; end++) {
            String sub = s.substring(idx, end);
            if (!used.contains(sub)) {
                java.util.Set<String> newSet = new java.util.HashSet<String>(used);
                newSet.add(sub);
                idxStack.push(end);
                setStack.push(newSet);
            }
        }
    }
    return best;
}

