    // Distribute the remaining value starting from the end to keep lexicographic order minimal
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int increment = Math.min(remaining, 25); // max we can add to an 'a'
        result[i] = (char) (result[i] + increment);
        remaining -= increment;
    }

    return new String(result);
}

