    return 0.5;
}

public static int singleNumber(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0; // No element to process
    }
    int[] bitCount = new int[32];
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            bitCount[i] += (num >>> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if ((bitCount[i] % 3) != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    List<Integer> result = new ArrayList<>();
    if (low > high) {
        return result;
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        if (i > high) {
            continue;
        }
        queue.offer(i);
    }
    while (!queue.isEmpty()) {
        int num = queue.poll();
        if (num >= low && num <= high) {
            result.add(num);
        }
        // Do not generate next numbers from 0 to avoid leading zeros
        if (num == 0) {
            continue;
        }
        int lastDigit = num % 10;
        int next1 = (lastDigit - 1 >= 0) ? num * 10 + (lastDigit - 1) : -1;
        int next2 = (lastDigit + 1 <= 9) ? num * 10 + (lastDigit + 1) : -1;
        if (next1 != -1 && next1 <= high) {
            queue.offer(next1);
        }
        if (next2 != -1 && next2 <= high) {
            queue.offer(next2);
        }
    }
    Collections.sort(result);
    return result;
}

public static int countDigitOne(int n) {
    if (n <= 0) {
        return 0;
    }
    long count = 0;
    for (long multiplier = 1; multiplier <= n; multiplier *= 10) {
        long higher = n / (multiplier * 10);
        long cur = (n / multiplier) % 10;
        long lower = n % multiplier;
        if (cur == 0) {
            count += higher * multiplier;
        } else if (cur == 1) {
            count += higher * multiplier + lower + 1;
        } else { // cur > 1
            count += (higher + 1) * multiplier;
        }
    }
    return (int) count;
}

public static boolean isPowerOfTwo(int n) {
    // A power of two must be a positive integer.
    if (n <= 0) {
        return false;
    }
    // Using the property that a power of two has only one bit set.
    // n & (n - 1) will be zero only for powers of two.
    return (n & (n - 1)) == 0;
}

public static int addDigits(int num) {
    if (num < 0) {
        throw new IllegalArgumentException("Input must be non-negative");
    }
    while (num >= 10) {
        int sum = 0;
        while (num > 0) {
            sum += num % 10;
            num /= 10;
        }
        num = sum;
    }
    return num;
}

public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }
    int m = mat.length;
    int n = mat[0].length;
    int[][] horiz = new int[m][n];
    int[][] vert  = new int[m][n];
    int[][] diag  = new int[m][n];
    int[][] antiDiag = new int[m][n];
    int maxLen = 0;
    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                horiz[i][j] = (j > 0 ? horiz[i][j - 1] : 0) + 1;
                vert[i][j]  = (i > 0 ? vert[i - 1][j] : 0) + 1;
                diag[i][j]  = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                antiDiag[i][j] = (i > 0 && j < n - 1 ? antiDiag[i - 1][j + 1] : 0) + 1;
                int localMax = Math.max(Math.max(horiz[i][j], vert[i][j]),
                                        Math.max(diag[i][j], antiDiag[i][j]));
                if (localMax > maxLen) {
                    maxLen = localMax;
                }
            } // else all zeros remain 0
        }
    }
    return maxLen;
}

public static String addThousandSeparator(int n) {
    // Handle zero directly
    if (n == 0) {
        return "0";
    }

    // Preserve the sign
    boolean negative = n < 0;
    int absValue = Math.abs(n);
    String numberStr = Integer.toString(absValue);

    StringBuilder sb = new StringBuilder();
    int count = 0; // digits processed in current group

    // Iterate over the number string from the end
    for (int i = numberStr.length() - 1; i >= 0; i--) {
        sb.append(numberStr.charAt(i));
        count++;

        if (count == 3 && i > 0) {
            sb.append('.');
            count = 0;
        }
    }

    // Reverse to get the correct order
    sb.reverse();

    // Reattach the negative sign if needed
    if (negative) {
        sb.insert(0, '-');
    }

    return sb.toString();
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int idx = 0;
    for (int sum = 0; sum <= m + n - 2; sum++) {
        int startRow = Math.min(sum, m - 1);
        int endRow = Math.max(0, sum - n + 1);
        if (sum % 2 == 0) {
            for (int row = startRow; row >= endRow; row--) {
                int col = sum - row;
                result[idx++] = mat[row][col];
            }
        } else {
            for (int row = endRow; row <= startRow; row++) {
                int col = sum - row;
                result[idx++] = mat[row][col];
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        return -1;
    }
    // Convert number to digit array
    char[] digits = String.valueOf(n).toCharArray();
    int len = digits.length;

    // Find the largest index i such that digits[i] < digits[i+1]
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If no such index exists, the digits are in descending order
    if (i < 0) {
        return -1;
    }

    // Find the largest index j > i such that digits[j] > digits[i]
    int j = len - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }

    // Swap digits[i] and digits[j]
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Reverse the suffix starting at i+1
    int left = i + 1, right = len - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }

    // Convert back to integer, checking overflow
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            return -1;
        }
    }

    return (int) result;
}

public static List<String> centerSymmetricNumbers(int n) {
    if (n <= 0) {
        return java.util.Collections.emptyList();
    }
    return buildCenterSymmetric(n, true);
}

private static List<String> buildCenterSymmetric(int length, boolean top) {
    if (length == 0) {
        return java.util.Collections.singletonList("");
    }
    if (length == 1) {
        return java.util.Arrays.asList("0", "1", "8");
    }

    List<String> sub = buildCenterSymmetric(length - 2, false);
    List<String> result = new java.util.ArrayList<>();
    char[][] pairs = { {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'} };

    for (String inner : sub) {
        for (char[] pair : pairs) {
            if (top && pair[0] == '0') {
                continue; // skip leading zero for top level
            }
            result.add(pair[0] + inner + pair[1]);
        }
    }
    return result;
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }
    try {
        int[] p1 = points[0];
        int[] p2 = points[1];
        int[] p3 = points[2];
        if (p1 == null || p2 == null || p3 == null) {
            return false;
        }
        if (p1.length != 2 || p2.length != 2 || p3.length != 2) {
            return false;
        }
        // Check that all points are distinct
        if (p1[0] == p2[0] && p1[1] == p2[1]) return false;
        if (p1[0] == p3[0] && p1[1] == p3[1]) return false;
        if (p2[0] == p3[0] && p2[1] == p3[1]) return false;
        // Compute cross product to test colinearity
        long cross = (long)(p2[0] - p1[0]) * (p3[1] - p1[1]) -
                     (long)(p3[0] - p1[0]) * (p2[1] - p1[1]);
        return cross != 0;
    } catch (Exception e) {
        return false;
    }
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("n must be a positive integer");
    }

    int[] ugly = new int[n];
    ugly[0] = 1;

    int i2 = 0, i3 = 0, i5 = 0;
    long next2 = 2L, next3 = 3L, next5 = 5L;
    int result = 1;

    for (int i = 1; i < n; i++) {
        long next = Math.min(next2, Math.min(next3, next5));
        ugly[i] = (int) next;
        result = (int) next;

        if (next == next2) {
            i2++;
            next2 = (long) ugly[i2] * 2L;
        }
        if (next == next3) {
            i3++;
            next3 = (long) ugly[i3] * 3L;
        }
        if (next == next5) {
            i5++;
            next5 = (long) ugly[i5] * 5L;
        }
    }

    return result;
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            current = 1;
        }
        if (current > max) {
            max = current;
        }
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>();
    if (n < 1) {
        return result;
    }
    try {
        for (int i = 1; i <= 9; i++) {
            dfs(i, n, result);
        }
    } catch (StackOverflowError e) {
        // In case recursion depth is exceeded, fallback to iterative approach
        result.clear();
        long cur = 1;
        while (cur <= n) {
            result.add((int) cur);
            if (cur * 10 <= n) {
                cur *= 10;
            } else {
                if (cur % 10 != 9 && cur + 1 <= n) {
                    cur++;
                } else {
                    cur /= 10;
                    while ((cur % 10 == 9 || cur + 1 > n) && cur > 0) {
                        cur /= 10;
                    }
                    cur++;
                }
            }
        }
    }
    return result;
}

private static void dfs(long curr, int n, List<Integer> res) {
    if (curr > n) {
        return;
    }
    res.add((int) curr);
    if (curr <= n / 10) { // check curr*10 <= n without overflow
        for (int i = 0; i <= 9; i++) {
            long next = curr * 10 + i;
            if (next > n) {
                break;
            }
            dfs(next, n, res);
        }
    }
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> countMap = new java.util.HashMap<>();
    for (int num : nums) {
        countMap.put(num, countMap.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : countMap.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n < 0) {
        return -1;
    }
    if (n == 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    for (int i = 0; i <= n; i++) {
        dp[i] = i; // worst case: i times 1^2
    }
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int maxRoot = (int) Math.sqrt(i);
        for (int j = 1; j <= maxRoot; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // Append reversed current word and the space
            result.append(word.reverse());
            word.setLength(0); // reset word builder
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word if any
    if (word.length() > 0) {
        result.append(word.reverse());
    }
    return result.toString();
}
